// hendz
gsap.registerPlugin(ScrollTrigger);

function initNumberTrain() {
  const trains = document.querySelectorAll('.track_train_container');

  trains.forEach((train) => {
    const track = train.querySelector('.number_track');
    const value = parseInt(train.dataset.number, 10);
    const direction = train.dataset.direction || 'up';
    const delay = parseFloat(train.dataset.delay) || 0;
    const duration = parseFloat(train.dataset.duration) || 2;

    const targetY = -(value * 10);
    
    // Offset konstan untuk speed yang konsisten (lompat 4 angka)
    const offset = 40; 
    let startY = (direction === 'up') ? targetY + offset : targetY - offset;

    // Clamp agar visual tetap solid
    startY = Math.min(0, Math.max(-90, startY));

    // Set Initial
    gsap.set(track, { yPercent: startY });

    // Animasi Spontan
    gsap.to(track, {
      yPercent: targetY,
      duration: duration, // Speed konsisten di 1 detik
      delay: delay,
      ease: "back.out(0.05)", // Efek membal (spontan)
      scrollTrigger: {
        trigger: train,
        start: "top 95%",
        toggleActions: "play none none none"
      }
    });
  });
}

window.addEventListener('load', initNumberTrain);
